  // ---- popovers on the input: placed where they fit ----
  // Above the form, over the lines, when there is room (the chat column and phones: the form is near the window's
  // bottom); else below it (an older page's panel). Their height is capped to the room on that side, so they never leave
  // the window (the colour popup's bug: it opened downward, off-screen).
  function popPlace(pop, want) {
    const f = formEl.getBoundingClientRect(), vv = window.visualViewport;
    const top = vv ? vv.offsetTop : 0, bottom = top + (vv ? vv.height : innerHeight);
    const up = f.top - top - 8, down = bottom - f.bottom - 8;
    const useUp = up >= Math.min(want, 220) || up >= down;
    pop.style.top = useUp ? 'auto' : 'calc(100% + 4px)'; pop.style.bottom = useUp ? 'calc(100% + 4px)' : 'auto';
    pop.style.maxHeight = `${Math.max(120, Math.min(want, useUp ? up : down))}px`;
  }

